-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/jeuno/Hook_Line_and_Sinker.lua"]={["Path"]="scripts/quests/jeuno/Hook_Line_and_Sinker.lua",["SHA256"]="dc11ae410809d49ce126f500a14646d5610421770a2118beae1422e51b473f24",["Text"]="-----------------------------------\n-- Hook, Line, and Sinker\n-- Omer, Lower Jeuno: !pos -89.43 0 -124.1 245\n-- EGRET_FISHING_ROD: !additem 1726\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.HOOK_LINE_AND_SINKER)\n\nquest.reward =\n{\n    gil = 3000,\n    title = xi.title.ROD_RETRIEVER,\n}\n\nquest.sections =\n{\n    -- After completing A Vessel Without a Captain, talk to Omer to begin the quest.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getCurrentMission(xi.mission.log_id.COP) > xi.mission.id.cop.A_VESSEL_WITHOUT_A_CAPTAIN\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Omer'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(10040, 0, xi.item.THREE_EYED_FISH_1, xi.item.CRESCENT_FISH, 0, xi.item.EGRET_FISHING_ROD)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10040] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Obtain an Egret Fishing Rod, which drops from Sea Bishops and Krakens fished up on Qufim Island. No skill is required to hook these.\n    -- Return it to Omer to complete the quest.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Omer'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(10041, 0, 0, 0, 0, xi.item.EGRET_FISHING_ROD)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.EGRET_FISHING_ROD) then\n                        return quest:progressEvent(10042, 0, 0, 0, 0, xi.item.EGRET_FISHING_ROD)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10042] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/In_the_Mood_for_Love.lua"]={["Path"]="scripts/quests/jeuno/In_the_Mood_for_Love.lua",["SHA256"]="6fa4ce1db49c771132e1fe0d61635edf3824dd51fa99eba93155da3d04fc2ba5",["Text"]="-----------------------------------\n-- In the Mood for Love\n-----------------------------------\n-- Log ID: 3, Quest ID: 69\n-- Odasel  !pos -58 -6 -111 245\n-- Matoaka !pos -37 -6 -122 245\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.IN_THE_MOOD_FOR_LOVE)\n\nquest.reward =\n{\n    gil = 4800,\n    title = xi.title.PICK_UP_ARTIST,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getCurrentMission(xi.mission.log_id.COP) > xi.mission.id.cop.A_VESSEL_WITHOUT_A_CAPTAIN\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Odasel'] = quest:progressEvent(10035, 0, xi.item.CHAMELEON_DIAMOND),\n\n            onEventFinish =\n            {\n                [10035] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Odasel'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(10037, 0, xi.item.CHAMELEON_DIAMOND)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.CHAMELEON_DIAMOND) then\n                        return quest:progressEvent(10036, 0, xi.item.CHAMELEON_DIAMOND)\n                    end\n                end,\n            },\n            onEventFinish =\n            {\n                [10036] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:confirmTrade()\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Odasel'] = quest:event(10038):replaceDefault(),\n\n            ['Matoaka'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        -- Additional Cutscene\n                        return quest:progressEvent(10039)\n                    end\n                end,\n            },\n            onEventFinish =\n            {\n                [10039] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 0)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB01_In_Defiant_Challenge.lua"]={["Path"]="scripts/quests/jeuno/LB01_In_Defiant_Challenge.lua",["SHA256"]="a1848919bb2187b13901d00d7395d4c558c67d92c4624beeb329cb7159c510b3",["Text"]="-----------------------------------\n-- In Defiant Challenge\n-----------------------------------\n-- Log ID: 3, Quest ID: 128\n-- Maat : !pos 8 3 118 243\n-- Crawlers Nest\n-- qm10 : !pos -83.391 -8.222 79.065 197\n-- qm11 : !pos 98.081 -38.75 -181.198 197\n-- qm12 : !pos 99.326 -0.126 -188.869 197\n-- Garlaige Citadel\n-- qm18 : !pos -13.425, -1.176, 191.669 200\n-- qm19 : !pos -50.175 6.264 251.669 200\n-- qm20 : !pos -137.047 0 347.502 200\n-- The Eldieme Necropolis\n-- qm7 : !pos 252.824 -32.000 -64.803 195\n-- qm8 : !pos 105.275 -32 92.551 195\n-- qm9 : !pos 92.272 -32 -64.676 195\n-----------------------------------\nlocal crawlersID = zones[xi.zone.CRAWLERS_NEST]\nlocal eldiemeID  = zones[xi.zone.THE_ELDIEME_NECROPOLIS]\nlocal garlaigeID = zones[xi.zone.GARLAIGE_CITADEL]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.IN_DEFIANT_CHALLENGE)\n\nlocal keyItemTable =\n{\n    [xi.zone.CRAWLERS_NEST         ] = { xi.item.CLUMP_OF_EXORAY_MOLD,     crawlersID.text.COMBINE_INTO_A_CLUMP,     crawlersID.text.ITEM_CANNOT_BE_OBTAINED, xi.keyItem.EXORAY_MOLD_CRUMB1,     xi.keyItem.EXORAY_MOLD_CRUMB2,     xi.keyItem.EXORAY_MOLD_CRUMB3     },\n    [xi.zone.GARLAIGE_CITADEL      ] = { xi.item.CHUNK_OF_BOMB_COAL,       garlaigeID.text.COMBINE_INTO_A_CHUNK,     garlaigeID.text.ITEM_CANNOT_BE_OBTAINED, xi.keyItem.BOMB_COAL_FRAGMENT1,    xi.keyItem.BOMB_COAL_FRAGMENT2,    xi.keyItem.BOMB_COAL_FRAGMENT3    },\n    [xi.zone.THE_ELDIEME_NECROPOLIS] = { xi.item.PIECE_OF_ANCIENT_PAPYRUS, eldiemeID.text.PUT_TOGUETHER_TO_COMPLETE, eldiemeID.text.ITEM_CANNOT_BE_OBTAINED,  xi.keyItem.ANCIENT_PAPYRUS_SHRED1, xi.keyItem.ANCIENT_PAPYRUS_SHRED2, xi.keyItem.ANCIENT_PAPYRUS_SHRED3 },\n}\n\n-- Key Item removals. Needs to be called separately by the quest cleanup.\nlocal function cleanKeyItemSet(player, zoneId)\n    player:delKeyItem(keyItemTable[zoneId][4])\n    player:delKeyItem(keyItemTable[zoneId][5])\n    player:delKeyItem(keyItemTable[zoneId][6])\nend\n\n-- NOTE: This is handled in such an unconventional manner just so the text appears in the same order as in retail.\nlocal function handleQMTrigger(player, zoneId, rewardKI)\n    -- Era setting.\n    if xi.settings.main.OLDSCHOOL_G1 then\n        return\n    end\n\n    local itemId = keyItemTable[zoneId][1]\n\n    -- Give KI.\n    if\n        not player:hasItem(itemId) and  -- KI wont be given if we already possess the regular item.\n        not player:hasKeyItem(rewardKI) -- KI wont be given if we already possess the key item.\n    then\n        npcUtil.giveKeyItem(player, rewardKI)\n    end\n\n    -- Handle KI set fusion.\n    if\n        player:hasKeyItem(keyItemTable[zoneId][4]) and\n        player:hasKeyItem(keyItemTable[zoneId][5]) and\n        player:hasKeyItem(keyItemTable[zoneId][6])\n    then\n        if\n            not player:hasItem(itemId) and\n            player:getFreeSlotsCount() > 0\n        then\n            cleanKeyItemSet(player, zoneId)\n            player:messageSpecial(keyItemTable[zoneId][2], rewardKI)\n            npcUtil.giveItem(player, itemId)\n        else\n            player:messageSpecial(keyItemTable[zoneId][3], itemId)\n        end\n    end\nend\n\nquest.reward =\n{\n    title    = xi.title.HORIZON_BREAKER,\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() == 50 and\n                player:getLevelCap() == 50 and\n                xi.settings.main.MAX_LEVEL >= 55\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(79)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [79] = function(player, csid, option, npc)\n                    if option == 1 then -- Accept quest option.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(80)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.CLUMP_OF_EXORAY_MOLD, xi.item.CHUNK_OF_BOMB_COAL, xi.item.PIECE_OF_ANCIENT_PAPYRUS }) then\n                        return quest:progressEvent(81)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [81] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        -- Remove all remaining/lingering KIs\n                        cleanKeyItemSet(player, xi.zone.CRAWLERS_NEST)\n                        cleanKeyItemSet(player, xi.zone.GARLAIGE_CITADEL)\n                        cleanKeyItemSet(player, xi.zone.THE_ELDIEME_NECROPOLIS)\n                        -- Finish\n                        player:confirmTrade()\n                        player:setLevelCap(55)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.CRAWLERS_NEST] =\n        {\n            ['qm10'] =\n            {\n                onTrigger = function(player, npc)\n                    handleQMTrigger(player, xi.zone.CRAWLERS_NEST, xi.keyItem.EXORAY_MOLD_CRUMB1)\n                end,\n            },\n\n            ['qm11'] =\n            {\n                onTrigger = function(player, npc)\n                    handleQMTrigger(player, xi.zone.CRAWLERS_NEST, xi.keyItem.EXORAY_MOLD_CRUMB2)\n                end,\n            },\n\n            ['qm12'] =\n            {\n                onTrigger = function(player, npc)\n                    handleQMTrigger(player, xi.zone.CRAWLERS_NEST, xi.keyItem.EXORAY_MOLD_CRUMB3)\n                end,\n            },\n        },\n\n        [xi.zone.GARLAIGE_CITADEL] =\n        {\n            ['qm18'] =\n            {\n                onTrigger = function(player, npc)\n                    handleQMTrigger(player, xi.zone.GARLAIGE_CITADEL, xi.keyItem.BOMB_COAL_FRAGMENT1)\n                end,\n            },\n\n            ['qm19'] =\n            {\n                onTrigger = function(player, npc)\n                    handleQMTrigger(player, xi.zone.GARLAIGE_CITADEL, xi.keyItem.BOMB_COAL_FRAGMENT2)\n                end,\n            },\n\n            ['qm20'] =\n            {\n                onTrigger = function(player, npc)\n                    handleQMTrigger(player, xi.zone.GARLAIGE_CITADEL, xi.keyItem.BOMB_COAL_FRAGMENT3)\n                end,\n            },\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS] =\n        {\n            ['qm7'] =\n            {\n                onTrigger = function(player, npc)\n                    handleQMTrigger(player, xi.zone.THE_ELDIEME_NECROPOLIS, xi.keyItem.ANCIENT_PAPYRUS_SHRED1)\n                end,\n            },\n\n            ['qm8'] =\n            {\n                onTrigger = function(player, npc)\n                    handleQMTrigger(player, xi.zone.THE_ELDIEME_NECROPOLIS, xi.keyItem.ANCIENT_PAPYRUS_SHRED2)\n                end,\n            },\n\n            ['qm9'] =\n            {\n                onTrigger = function(player, npc)\n                    handleQMTrigger(player, xi.zone.THE_ELDIEME_NECROPOLIS, xi.keyItem.ANCIENT_PAPYRUS_SHRED3)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB02_Atop_the_Highest_Mountains.lua"]={["Path"]="scripts/quests/jeuno/LB02_Atop_the_Highest_Mountains.lua",["SHA256"]="64f292f8f6c707b106538846e0aef871a11ad95745c2eb1c6c143488ba29811d",["Text"]="-----------------------------------\n-- Atop the Highest Mountains\n-----------------------------------\n-- Log ID: 3, Quest ID: 129\n-- Maat : !pos 8 3 118 243\n-- Xarcabard\n-- qm2 : !pos 341 -29 370 112\n-- qm3 : !pos 580 -9 290 112\n-- qm4 : !pos -21 -25 -490 112\n-----------------------------------\nlocal ruludeID    = zones[xi.zone.RULUDE_GARDENS]\nlocal xarcabardID = zones[xi.zone.XARCABARD]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.ATOP_THE_HIGHEST_MOUNTAINS)\n\nquest.reward =\n{\n    title = xi.title.SUMMIT_BREAKER,\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getLevelCap() == 55 and\n                xi.settings.main.MAX_LEVEL >= 60\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= 51 then\n                        return quest:progressEvent(82)\n                    else\n                        return quest:messageText(ruludeID.text.MAAT_LB2_PLACEHOLDER)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [82] = function(player, csid, option, npc)\n                    if option == 1 then -- Accept quest option.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.ROUND_FRIGICITE) and\n                        player:hasKeyItem(xi.keyItem.SQUARE_FRIGICITE) and\n                        player:hasKeyItem(xi.keyItem.TRIANGULAR_FRIGICITE)\n                    then\n                        return quest:progressEvent(84)\n                    else\n                        return quest:event(83)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [84] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.ROUND_FRIGICITE)\n                        player:delKeyItem(xi.keyItem.SQUARE_FRIGICITE)\n                        player:delKeyItem(xi.keyItem.TRIANGULAR_FRIGICITE)\n                        player:setLevelCap(60)\n                        player:messageSpecial(ruludeID.text.YOUR_LEVEL_LIMIT_IS_NOW_60)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.XARCABARD] =\n        {\n            ['qm_boreal_tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.ROUND_FRIGICITE) and\n                        (not xi.settings.main.OLDSCHOOL_G2 or GetMobByID(xarcabardID.mob.BOREAL_TIGER):isDead())\n                    then\n                        return quest:keyItem(xi.keyItem.ROUND_FRIGICITE)\n                    end\n                end,\n            },\n\n            ['qm_boreal_coeurl'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.SQUARE_FRIGICITE) and\n                        (not xi.settings.main.OLDSCHOOL_G2 or GetMobByID(xarcabardID.mob.BOREAL_COEURL):isDead())\n                    then\n                        return quest:keyItem(xi.keyItem.SQUARE_FRIGICITE)\n                    end\n                end,\n            },\n\n            ['qm_boreal_hound'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.TRIANGULAR_FRIGICITE) and\n                        (not xi.settings.main.OLDSCHOOL_G2 or GetMobByID(xarcabardID.mob.BOREAL_HOUND):isDead())\n                    then\n                        return quest:keyItem(xi.keyItem.TRIANGULAR_FRIGICITE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB03_Whence_Blows_the_wind.lua"]={["Path"]="scripts/quests/jeuno/LB03_Whence_Blows_the_wind.lua",["SHA256"]="c218f17d3ab210b6a1c696ab3ca9fe0cd4795076dfe6507dc9351289fd1d321a",["Text"]="-----------------------------------\n-- Whence Blows the Wind\n-----------------------------------\n-- Log ID: 3, Quest ID: 130\n-- Maat : !pos 8 3 118 243\n-- qm1 (Monastic Caverns) : !pos 168 -1 -22 150\n-- qm2 (Castle Oztroja)   : !pos -100 -63 58 151\n-- qm1 (Qulun Dome)       : !pos 261 39 79 148\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.WHENCE_BLOWS_THE_WIND)\n\nquest.reward =\n{\n    title = xi.title.SKY_BREAKER,\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getLevelCap() == 60 and\n                xi.settings.main.MAX_LEVEL >= 65\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainLvl() >= 56 then\n                        return quest:progressEvent(85)\n                    else\n                        return quest:messageText(ruludeID.text.MAAT_LB3_PLACEHOLDER)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [85] = function(player, csid, option, npc)\n                    if option == 1 then -- Accept quest option.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.ORCISH_CREST) and\n                        player:hasKeyItem(xi.keyItem.QUADAV_CREST) and\n                        player:hasKeyItem(xi.keyItem.YAGUDO_CREST)\n                    then\n                        return quest:progressEvent(87)\n                    else\n                        return quest:event(86)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [87] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.ORCISH_CREST)\n                        player:delKeyItem(xi.keyItem.QUADAV_CREST)\n                        player:delKeyItem(xi.keyItem.YAGUDO_CREST)\n                        player:setLevelCap(65)\n                        player:messageSpecial(ruludeID.text.YOUR_LEVEL_LIMIT_IS_NOW_65)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.CASTLE_OZTROJA] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.YAGUDO_CREST) then\n                        return quest:keyItem(xi.keyItem.YAGUDO_CREST)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.MONASTIC_CAVERN] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.ORCISH_CREST) then\n                        return quest:keyItem(xi.keyItem.ORCISH_CREST)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.QULUN_DOME] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.QUADAV_CREST) then\n                        return quest:keyItem(xi.keyItem.QUADAV_CREST)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB04_Riding_on_the_clouds.lua"]={["Path"]="scripts/quests/jeuno/LB04_Riding_on_the_clouds.lua",["SHA256"]="f316e588900d182b8b723dcf6c5015ff5c2ebb0b3b4755d0debc0936014fd8fd",["Text"]="-----------------------------------\n-- Riding on the Clouds\n-----------------------------------\n-- Log ID: 3, Quest ID: 131\n-- Maat : !pos 8 3 118 243\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.RIDING_ON_THE_CLOUDS)\n\nlocal function handleSandoriaTrade(player, npc, trade)\n    if npcUtil.tradeHasExactly(trade, xi.item.KINDREDS_SEAL) then\n        quest:setVar(player, 'npcSandoria', 8)\n        player:confirmTrade()\n        npcUtil.giveKeyItem(player, xi.keyItem.SCOWLING_STONE)\n    end\nend\n\nlocal function handleBastokTrade(player, npc, trade)\n    if npcUtil.tradeHasExactly(trade, xi.item.KINDREDS_SEAL) then\n        quest:setVar(player, 'npcBastok', 8)\n        player:confirmTrade()\n        npcUtil.giveKeyItem(player, xi.keyItem.SMILING_STONE)\n    end\nend\n\nlocal function handleWindurstTrade(player, npc, trade)\n    if npcUtil.tradeHasExactly(trade, xi.item.KINDREDS_SEAL) then\n        quest:setVar(player, 'npcWindurst', 8)\n        player:confirmTrade()\n        npcUtil.giveKeyItem(player, xi.keyItem.SPIRITED_STONE)\n    end\nend\n\nlocal function handleOtherlandsTrade(player, npc, trade)\n    if npcUtil.tradeHasExactly(trade, xi.item.KINDREDS_SEAL) then\n        quest:setVar(player, 'npcOtherlands', 8)\n        player:confirmTrade()\n        npcUtil.giveKeyItem(player, xi.keyItem.SOMBER_STONE)\n    end\nend\n\nquest.reward =\n{\n    title = xi.title.CLOUD_BREAKER,\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= 61 and\n                player:getLevelCap() == 65 and\n                xi.settings.main.MAX_LEVEL >= 70\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    quest:setVar(player, 'npcSandoria', math.randomInt(0, 7))\n                    quest:setVar(player, 'npcBastok', math.randomInt(0, 7))\n                    quest:setVar(player, 'npcWindurst', math.randomInt(0, 7))\n                    quest:setVar(player, 'npcOtherlands', math.randomInt(0, 7))\n                    return quest:progressEvent(88,\n                        quest:getVar(player, 'npcSandoria'),\n                        quest:getVar(player, 'npcBastok'),\n                        quest:getVar(player, 'npcWindurst'),\n                        quest:getVar(player, 'npcOtherlands'),\n                        180)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [88] = function(player, csid, option, npc)\n                    if option == 1 then -- Accept quest option.\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'npcSandoria', 0)\n                        quest:setVar(player, 'npcBastok', 0)\n                        quest:setVar(player, 'npcWindurst', 0)\n                        quest:setVar(player, 'npcOtherlands', 0)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.SMILING_STONE) and\n                        player:hasKeyItem(xi.keyItem.SCOWLING_STONE) and\n                        player:hasKeyItem(xi.keyItem.SOMBER_STONE) and\n                        player:hasKeyItem(xi.keyItem.SPIRITED_STONE)\n                    then\n                        return quest:progressEvent(90) -- Finish Quest \"Riding on the Clouds\"\n                    else\n                        return quest:event(89,\n                            quest:getVar(player, 'npcSandoria'),\n                            quest:getVar(player, 'npcBastok'),\n                            quest:getVar(player, 'npcWindurst'),\n                            quest:getVar(player, 'npcOtherlands'),\n                            180) -- NPC reminder.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [90] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.SCOWLING_STONE)\n                        player:delKeyItem(xi.keyItem.SMILING_STONE)\n                        player:delKeyItem(xi.keyItem.SOMBER_STONE)\n                        player:delKeyItem(xi.keyItem.SPIRITED_STONE)\n                        player:setLevelCap(70)\n                        player:messageSpecial(ruludeID.text.YOUR_LEVEL_LIMIT_IS_NOW_70)\n                    end\n                end,\n            },\n        },\n\n        -- San d'Oria Zones and NPCs\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Raminel'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcSandoria') == 0 then\n                        handleSandoriaTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Sobane'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcSandoria') == 1 then\n                        handleSandoriaTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Taurette'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcSandoria') == 2 then\n                        handleSandoriaTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Maloquedil'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcSandoria') == 3 then\n                        handleSandoriaTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Sheridan'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcSandoria') == 4 then\n                        handleSandoriaTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Fontoumant'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcSandoria') == 5 then\n                        handleSandoriaTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Brifalien'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcSandoria') == 6 then\n                        handleSandoriaTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Rugiette'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcSandoria') == 7 then\n                        handleSandoriaTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n\n        -- Bastok Zones and NPCs\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Babenn'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcBastok') == 0 then\n                        handleBastokTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Gwill'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcBastok') == 1 then\n                        handleBastokTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Brygid'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcBastok') == 2 then\n                        handleBastokTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Kaede'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcBastok') == 3 then\n                        handleBastokTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Hilda'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcBastok') == 4 then\n                        handleBastokTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n        [xi.zone.METALWORKS] =\n        {\n            ['Naji'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcBastok') == 5 then\n                        handleBastokTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Raibaht'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcBastok') == 6 then\n                        handleBastokTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Lucius'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcBastok') == 7 then\n                        handleBastokTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n\n        -- Windurst Zones and NPCs\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Koko_Lihzeh'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcWindurst') == 0 then\n                        handleWindurstTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Naiko-Paneiko'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcWindurst') == 1 then\n                        handleWindurstTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Kerutoto'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcWindurst') == 2 then\n                        handleWindurstTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n        [xi.zone.WINDURST_WALLS] =\n        {\n            ['Koru-Moru'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcWindurst') == 3 then\n                        handleWindurstTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n        [xi.zone.PORT_WINDURST] =\n        {\n            ['Shanruru'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcWindurst') == 4 then\n                        handleWindurstTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Boizo-Naizo'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcWindurst') == 5 then\n                        handleWindurstTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Sola_Jaab'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcWindurst') == 6 then\n                        handleWindurstTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n        [xi.zone.HEAVENS_TOWER] =\n        {\n            ['Kupipi'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcWindurst') == 7 then\n                        handleWindurstTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n\n        -- Otherlands (Selbina and Mhaura) Zones and NPCs\n        [xi.zone.SELBINA] =\n        {\n            ['Mathilde'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcOtherlands') == 0 then\n                        handleOtherlandsTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Vobo'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcOtherlands') == 1 then\n                        handleOtherlandsTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Melyon'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcOtherlands') == 2 then\n                        handleOtherlandsTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Gabwaleid'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcOtherlands') == 3 then\n                        handleOtherlandsTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n        [xi.zone.MHAURA] =\n        {\n            ['Celestina'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcOtherlands') == 4 then\n                        handleOtherlandsTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Ekokoko'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcOtherlands') == 5 then\n                        handleOtherlandsTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Bihoro-Guhoro'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcOtherlands') == 6 then\n                        handleOtherlandsTrade(player, npc, trade)\n                    end\n                end,\n            },\n            ['Jikka-Abukka'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'npcOtherlands') == 7 then\n                        handleOtherlandsTrade(player, npc, trade)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB05_1_Shattering_Stars.lua"]={["Path"]="scripts/quests/jeuno/LB05_1_Shattering_Stars.lua",["SHA256"]="4845b74123622183542f45018d7d2c18a5b88690fd75b428c35d3ff5eb59b229",["Text"]="-----------------------------------\n-- Shattering Stars\n-----------------------------------\n-- Log ID: 3, Quest ID: 132\n-- Maat : !pos 8 3 118 243\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.SHATTERING_STARS)\n\nquest.reward =\n{\n    title    = xi.title.STAR_BREAKER,\n}\n\nlocal maatBattlefieldIds =\n{\n    [xi.zone.BALGAS_DAIS]        = { 101, 102, 103 },\n    [xi.zone.CHAMBER_OF_ORACLES] = { 194, 195, 196 },\n    [xi.zone.HORLAIS_PEAK]       = {   5,   6,   7 },\n    [xi.zone.QUBIA_ARENA]        = { 517, 518, 519 },\n    [xi.zone.WAUGHROON_SHRINE]   = {  70,  71,  72 },\n}\n\nlocal maatBattlefieldZone =\n{\n    onEventFinish =\n    {\n        [32001] = function(player, csid, option, npc)\n            local battlefieldWin = player:getLocalVar('battlefieldWin')\n\n            for _, battlefieldId in ipairs(maatBattlefieldIds[player:getZoneID()]) do\n                if battlefieldWin == battlefieldId then\n                    local jobId        = player:getMainJob()\n                    local maatsCapMask = player:getCharVar('maatsCap')\n\n                    if player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.SHATTERING_STARS) == xi.questStatus.QUEST_ACCEPTED then\n                        npcUtil.giveItem(player, xi.item.SCROLL_OF_INSTANT_WARP)\n                        quest:setVar(player, 'Prog', jobId)\n                    end\n\n                    if not utils.mask.getBit(maatsCapMask, jobId - 1) then\n                        player:setCharVar('maatsCap', utils.mask.setBit(maatsCapMask, jobId - 1, true))\n                    end\n\n                    player:addTitle(xi.title.MAAT_MASHER)\n                end\n            end\n        end,\n    },\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() <= 15 and -- Only the \"old\" jobs may start this quest.\n                player:getMainLvl() >= 66 and\n                player:getLevelCap() == 70 and\n                xi.settings.main.MAX_LEVEL >= 75\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(92, player:getMainJob())\n                end,\n            },\n\n            onEventFinish =\n            {\n                [92] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:getMainJob() <= 15 and\n                player:getMainLvl() >= 66\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local playerJob       = player:getMainJob()\n                    local properTestimony = xi.item.WARRIORS_TESTIMONY + playerJob - 1\n\n                    if\n                        trade:getItemQty(properTestimony) > 0 and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        return quest:progressEvent(64, playerJob)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local playerJob = player:getMainJob()\n\n                    if quest:getVar(player, 'Prog') >= 1 then\n                        return quest:progressEvent(93) -- Complete quest.\n                    elseif quest:getVar(player, 'tradedTestimony') == 0 then\n                        return quest:event(91, playerJob) -- Testimony never traded.\n                    else\n                        return quest:event(63, playerJob) -- Testimony traded at least once.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [64] = function(player, csid, option, npc)\n                    quest:setVar(player, 'tradedTestimony', 1)\n\n                    -- Accept teleport.\n                    if option == 1 then\n                        local mJob = player:getMainJob()\n                        if mJob == xi.job.MNK or mJob == xi.job.WHM or mJob == xi.job.SMN then\n                            player:setPos(299.316, -123.591, 353.760, 66, 146)\n                        elseif mJob == xi.job.WAR or mJob == xi.job.BLM or mJob == xi.job.RNG then\n                            player:setPos(-511.459, 159.004, -210.543, 10, 139)\n                        elseif mJob == xi.job.PLD or mJob == xi.job.DRK or mJob == xi.job.BRD then\n                            player:setPos(-225.146, -24.250, 20.057, 255, 206)\n                        elseif mJob == xi.job.RDM or mJob == xi.job.THF or mJob == xi.job.BST then\n                            player:setPos(-349.899, 104.213, -260.150, 0, 144)\n                        elseif mJob == xi.job.SAM or mJob == xi.job.NIN or mJob == xi.job.DRG then\n                            player:setPos(-220.084, -0.645, 4.442, 191, 168)\n                        end\n                    end\n                end,\n\n                [93] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setLevelCap(75)\n                        player:messageSpecial(ruludeID.text.YOUR_LEVEL_LIMIT_IS_NOW_75)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status >= xi.questStatus.QUEST_ACCEPTED and\n                player:getMainJob() <= 15 and\n                player:getMainLvl() >= 66\n        end,\n\n        [xi.zone.BALGAS_DAIS]        = maatBattlefieldZone,\n        [xi.zone.CHAMBER_OF_ORACLES] = maatBattlefieldZone,\n        [xi.zone.HORLAIS_PEAK]       = maatBattlefieldZone,\n        [xi.zone.QUBIA_ARENA]        = maatBattlefieldZone,\n        [xi.zone.WAUGHROON_SHRINE]   = maatBattlefieldZone,\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB05_2_Beyond_the_Sun.lua"]={["Path"]="scripts/quests/jeuno/LB05_2_Beyond_the_Sun.lua",["SHA256"]="ece1eedafe5ac954e22674d9684ec8c29c99d947d76babd694d21180c8131a9d",["Text"]="-----------------------------------\n-- Beyond the Sun\n-----------------------------------\n-- Log ID: 3, Quest ID: 76\n-- Maat : !pos 8 3 118 243\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.BEYOND_THE_SUN)\n\nquest.reward =\n{\n    item = xi.item.MAATS_CAP,\n    title = xi.title.ULTIMATE_CHAMPION_OF_THE_WORLD,\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.SHATTERING_STARS) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getMainJob() <= 15 then\n                        if utils.mask.isFull(player:getCharVar('maatsCap'), 15) then -- Defeated maat on 15 jobs\n                            return quest:progressEvent(74)\n                        else\n                            return quest:event(78, player:getMainJob()) -- Rematch dialog. Job dependant.\n                        end\n                    else\n                        return quest:messageText(ruludeID.text.MAAT_CAP_PLACEHOLDER)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [74] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainJob() <= 15 and\n                        player:getMainLvl() >= 66\n                    then\n                        return quest:event(78, player:getMainJob())\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB06_New_Worlds_Await.lua"]={["Path"]="scripts/quests/jeuno/LB06_New_Worlds_Await.lua",["SHA256"]="94c68bb076979e694564623a8d17f3f39fc0befffc6dfd9dffa784239a07a174",["Text"]="-----------------------------------\n-- New Worlds Await\n-----------------------------------\n-- Log ID: 3, Quest ID: 133\n-- Nomad Moogle : !pos 10.012 1.453 121.883 243\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.NEW_WORLDS_AWAIT)\n\nquest.reward =\n{\n}\n\n-- Event 10045 is the global event used in all Limit break quest from 6 to 10.\n-- Parameter 1 -> player level.\n-- Parameter 2 -> player has the Limit Breaker KI (1) or not (2)\n-- Parameter 3 -> \"ID/number\" of current LB quest associated with this npc. LB-6 = 1, LB-7 = 2, LB-8 = 3...\n-- Parameter 4 -> progress in current quest.\n\nquest.sections =\n{\n    -- Section: Quest accepted. There is no quest pre-requisite.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getLevelCap() == 75\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 0\n                    local lastQuestStage  = 0\n                    if\n                        xi.settings.main.MAX_LEVEL > 75 and -- Can we level over 75?\n                        playerLevel == 75 and               -- Are we at limit level?\n                        limitBreaker == 1                   -- Do we have limit breaker KI? (Pre-requisite)\n                    then\n                        lastQuestNumber = 1\n                    end\n\n                    return quest:progressEvent(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage)\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [10045] = function(player, csid, option, npc)\n                    if option == 4 then\n                        player:updateEvent(243, 2, 3, 1, 17154, 0, 235339776, 4) -- I've taken 3 different captures and they always seem different.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10045] = function(player, csid, option, npc)\n                    -- Obtain Limit Breaker KI option.\n                    if option == 4 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.LIMIT_BREAKER)\n\n                    -- Accept LB6 quest option.\n                    elseif option == 5 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, { { xi.item.KINDREDS_SEAL, 5 } }) and\n                        player:getMeritCount() > 2\n                    then\n                        return quest:progressEvent(10135)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 1\n                    local lastQuestStage  = 1\n\n                    return quest:event(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage) -- Reminder.\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10135] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:setMerits(player:getMeritCount() - 3)\n                        player:setLevelCap(80)\n                        player:messageSpecial(ruludeID.text.YOUR_LEVEL_LIMIT_IS_NOW_80)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB07_Expanding_Horizons.lua"]={["Path"]="scripts/quests/jeuno/LB07_Expanding_Horizons.lua",["SHA256"]="204b93a606ee793d4ead1d674fc388051dbe23f5e2f050daf26e38ee1cf99f21",["Text"]="-----------------------------------\n-- Expanding Horizons\n-----------------------------------\n-- Log ID: 3, Quest ID: 134\n-- Nomad Moogle : !pos 10.012 1.453 121.883 243\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.EXPANDING_HORIZONS)\n\nquest.reward =\n{\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.NEW_WORLDS_AWAIT) and\n                player:getLevelCap() == 80\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 0\n                    local lastQuestStage  = 0\n                    if\n                        xi.settings.main.MAX_LEVEL > 80 and\n                        limitBreaker == 1\n                    then\n                        if playerLevel > 75 then\n                            lastQuestNumber = 2\n                        elseif playerLevel == 75 then\n                            lastQuestNumber = 1\n                            lastQuestStage  = 2\n                        end\n                    end\n\n                    return quest:progressEvent(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10045] = function(player, csid, option, npc)\n                    if option == 7 then -- Accept quest option.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, { { xi.item.KINDREDS_CREST, 5 } }) and\n                        player:getMeritCount() > 3\n                    then\n                        return quest:progressEvent(10136)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 2\n                    local lastQuestStage  = 1\n\n                    return quest:event(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10136] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                        player:setMerits(player:getMeritCount() - 4)\n                        player:setLevelCap(85)\n                        player:messageSpecial(ruludeID.text.YOUR_LEVEL_LIMIT_IS_NOW_85)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB08_Beyond_the_Stars.lua"]={["Path"]="scripts/quests/jeuno/LB08_Beyond_the_Stars.lua",["SHA256"]="c7b613dbd31c642a7d99702581754cbe613cf1f47058f52b4005785bcdfc88ef",["Text"]="-----------------------------------\n-- Beyond the Stars\n-----------------------------------\n-- Log ID: 3, Quest ID: 135\n-- Nomad Moogle : !pos 10.012 1.453 121.883 243\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.BEYOND_THE_STARS)\n\n-- TODO: Properly code the rock, paper, scissors minigame. Awaiting for a capture.\n-- Probably a matter of chaining onEventUpdates and tracking Maat's and Degengard's HP. Maybe not.\n-- It seems that the event tracks HP on it's own.\n-- Degengard's moves are selected at random.\n\nquest.reward =\n{\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.EXPANDING_HORIZONS) and\n                player:getLevelCap() == 85\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 0\n                    local lastQuestStage  = 0\n                    if\n                        xi.settings.main.MAX_LEVEL > 85 and\n                        limitBreaker == 1\n                    then\n                        if playerLevel > 80 then\n                            lastQuestNumber = 3\n                        elseif playerLevel >= 75 then\n                            lastQuestNumber = 2\n                            lastQuestStage  = 2\n                        end\n                    end\n\n                    return quest:progressEvent(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10045] = function(player, csid, option, npc)\n                    if option == 9 then -- Accept quest option.\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, { { xi.item.KINDREDS_CREST, 10 } }) and\n                        player:getMeritCount() > 4\n                    then\n                        return quest:progressEvent(10137)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 3\n                    local lastQuestStage  = 1\n\n                    -- Rock, Paper, Scissor Minigame.\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(10161, playerLevel, 0)\n\n                    -- Reminder\n                    else\n                        return quest:event(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage)\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [10161] = function(player, csid, option, npc)\n                    -- Maat move choice.\n                    local maatMove = 0\n                    if option == 21 then\n                        maatMove = 0 -- Red.\n                    elseif option == 22 then\n                        maatMove = 1 -- Blue.\n                    elseif option == 23 then\n                        maatMove = 2 -- Green.\n                    end\n\n                    -- Degenhard move choice.\n                    local degenhardMove = math.randomInt(0, 2)\n\n                    -- Rock-Paper-Scissors: Red beats Blue; Blue beats Green; Green beats Red.\n                    local clashOutcome = 1 -- Assume Degenhard wins\n                    if maatMove == degenhardMove then\n                        clashOutcome = 2 -- Draw\n                    elseif\n                        (maatMove == 0 and degenhardMove == 1) or\n                        (maatMove == 1 and degenhardMove == 2) or\n                        (maatMove == 2 and degenhardMove == 0)\n                    then\n                        clashOutcome = 0\n                    end\n\n                    local eventBitmask = maatMove + degenhardMove * 4 + clashOutcome * 16 -- Controls moves chosen by Maat and Degenhard, and who wins the round.\n                    player:updateEvent(eventBitmask)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10137] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:setMerits(player:getMeritCount() - 5)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [10161] = function(player, csid, option, npc)\n                    if option == 254 then\n                        quest:complete(player)\n                        player:setLevelCap(90)\n                        player:messageSpecial(ruludeID.text.YOUR_LEVEL_LIMIT_IS_NOW_90)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB09_1_Dormant_Powers_Dislodged.lua"]={["Path"]="scripts/quests/jeuno/LB09_1_Dormant_Powers_Dislodged.lua",["SHA256"]="4964a3c3aab32cc4462927c24a30f8f63ee696ac48a6ec80fb8f7a563e005959",["Text"]="-----------------------------------\n-- Dormant Powers Dislodged\n-----------------------------------\n-- Log ID: 3, Quest ID: 136\n-- Nomad Moogle : !pos 10.012 1.453 121.883 243\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.DORMANT_POWERS_DISLODGED)\n\n-- NOTE: Timing minigame was guesstimated! No capture available.\n-- The event seems to handle the actual timing. As in, it counts for us.\n-- Always the same camera angle at victory. That is, close up of player, at arround 9 seconds.\n-- Wining timing: 10 seconds aprox.\n\nlocal itemWantedTable =\n{\n    [0] = { xi.item.PINCH_OF_VALKURM_SUNSAND },\n    [1] = { xi.item.FADED_CRYSTAL            },\n    [2] = { xi.item.ORCISH_PLATE_ARMOR       },\n    [3] = { xi.item.MAGICKED_SKULL           },\n    [4] = { xi.item.CUP_OF_DHALMEL_SALIVA    },\n    [5] = { xi.item.YAGUDO_CAULK             },\n    [6] = { xi.item.SIRENS_TEAR              },\n    [7] = { xi.item.DANGRUF_STONE            },\n    [8] = { xi.item.ORCISH_AXE               },\n    [9] = { xi.item.QUADAV_BACKSCALE         },\n    -- 10+ = It repeats the pattern ad nauseam.\n}\n\nquest.reward =\n{\n    keyItem  = xi.keyItem.SOUL_GEM,\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.BEYOND_THE_STARS) and\n                player:getLevelCap() == 90\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 0\n                    local lastQuestStage  = 0\n                    local option          = quest:getVar(player, 'Option') -- Has rejected signing the contract?\n                    local itemChosen      = quest:getVar(player, 'itemWanted') - 1\n                    if\n                        xi.settings.main.MAX_LEVEL > 90 and\n                        limitBreaker == 1\n                    then\n                        if playerLevel > 85 then\n                            lastQuestNumber = 4\n                        elseif playerLevel >= 75 then\n                            lastQuestNumber = 3\n                            lastQuestStage  = 2\n                        end\n                    end\n\n                    -- Save item Chosen\n                    if itemChosen < 0 then\n                        itemChosen = math.randomInt(0, 9)\n                        quest:setVar(player, 'itemWanted', itemChosen + 1)\n                    end\n\n                    return quest:progressEvent(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage, option, itemChosen)\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [10045] = function(player, csid, option, npc)\n                    -- This event update checks if you have completed \"Beat Around the Bushin\" quest. If so, Atori-Tutori recognizes you.\n                    if option == 8 then\n                        local knowAtori = player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.BEAT_AROUND_THE_BUSHIN) and 1 or 0\n                        player:updateEvent(knowAtori)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10045] = function(player, csid, option, npc)\n                    -- Accept quest option.\n                    if option == 11 then\n                        quest:begin(player)\n\n                    -- Reject signing. Quest not added to log.\n                    elseif option == 12 then\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local itemWanted  = quest:getVar(player, 'itemWanted') - 1\n                    local itemToTrade = itemWantedTable[itemWanted][1]\n\n                    if\n                        npcUtil.tradeHasExactly(trade, { { xi.item.KINDREDS_CREST, 1 }, { itemToTrade, 1 } }) and\n                        player:getMeritCount() > 9\n                    then\n                        return quest:progressEvent(10191)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local playerLevel = player:getMainLvl()\n\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(10192, playerLevel, 0, 0, 2) -- Timing Minigame starting event.\n                    else\n                        local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                        local lastQuestNumber = 4\n                        local lastQuestStage  = 1\n                        local itemChosen      = quest:getVar(player, 'itemWanted')\n                        return quest:event(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage, 0, itemChosen)\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [10192] = function(player, csid, option, npc)\n                    -- Option: Push! The option is the number of frames. 1 sec = 60 frames. Probably.\n                    if option >= 780 then\n                        player:updateEvent(4) -- Over 13 seconds. Slime.\n                    elseif option >= 660 then\n                        player:updateEvent(3) -- Between 11 and 13 seconds.Big Egg.\n                    elseif option >= 540 then\n                        player:updateEvent(2) -- Between 9 and 11 seconds. Glowing Egg. Win!\n                    elseif option >= 420 then\n                        player:updateEvent(1) -- Between 7 and 9 seconds. Regular Egg.\n                    else\n                        player:updateEvent(0) -- Under 7 seconds. Mandragora.\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10191] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:setMerits(player:getMeritCount() - 10)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [10192] = function(player, csid, option, npc)\n                    if\n                        option >= 540 and\n                        option < 660\n                    then\n                        quest:complete(player)\n                        player:setLevelCap(95)\n                        player:messageSpecial(ruludeID.text.YOUR_LEVEL_LIMIT_IS_NOW_95)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB09_2_Prelude_to_Puissance.lua"]={["Path"]="scripts/quests/jeuno/LB09_2_Prelude_to_Puissance.lua",["SHA256"]="7f114162a30ff5647dea85b51afbc812f922a4a0e1af9e234bbd8ac1724c2c4d",["Text"]="-----------------------------------\n-- Prelude_to_Puissance\n-----------------------------------\n-- Log ID: 3, Quest ID: 170\n-- Nomad Moogle : !pos 10.012 1.453 121.883 243\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.PRELUDE_TO_PUISSANCE)\n\n-- TODO: Properly code timing minigame. Awaiting for a capture.\n-- Amount of visual qeues selected at random. Min: Probably 3. Max: 7. Camera angle keeps changing qithout hints.\n-- Always the same camera angle at victory.\n\nquest.reward =\n{\n    keyItem = xi.keyItem.SOUL_GEM_CLASP,\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.DORMANT_POWERS_DISLODGED) and\n                player:getLevelCap() == 95\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrigger = function(player, npc)\n                    local eventId         = 10045\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 0\n                    local lastQuestStage  = 0\n                    if\n                        xi.settings.main.MAX_LEVEL > 95 and\n                        limitBreaker == 1\n                    then\n                        if playerLevel > 90 then\n                            eventId         = 10194\n                            lastQuestNumber = 6\n                            lastQuestStage  = 2\n                        elseif playerLevel >= 75 then\n                            lastQuestNumber = 4\n                            lastQuestStage  = 2\n                        end\n                    end\n\n                    return quest:progressEvent(eventId, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10194] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'tradeCompleted') == 0 and\n                        npcUtil.tradeHasExactly(trade, xi.item.SEASONING_STONE)\n                    then\n                        quest:setVar(player, 'tradeCompleted', 1)\n                        player:confirmTrade()\n\n                        return quest:progressEvent(10045, 0, 1, 5, 0)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 6\n                    local lastQuestStage  = 2\n                    if quest:getVar(player, 'tradeCompleted') > 0 then\n                        lastQuestNumber = 5\n                        lastQuestStage  = 0\n                    end\n\n                    return quest:progressEvent(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage, 0)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10045] = function(player, csid, option, npc)\n                    -- All this options complete the current quest.\n                    if\n                        option == 0 or\n                        option == 13 or\n                        option == 14 or\n                        option == 15 or\n                        option == 19 or\n                        option == 20 or\n                        option == 21\n                    then\n                        -- Rejected offer. Still completes quest.\n                        if option == 15 then\n                            player:setLocalVar('rejectedStartLB10', 1)\n                        end\n\n                        -- Complete quest.\n                        if quest:complete(player) then\n                            -- This options immediately start next quest. (All except 0 and 15).\n                            if\n                                option ~= 0 and\n                                option ~= 15\n                            then\n                                player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.BEYOND_INFINITY)\n                            end\n\n                            -- This options also warp you to a BCNM. Note that the quest \"Beyond Infinity\" is already activated in this cases.\n                            if option == 14 then\n                                player:setPos(-511.459, 159.004, -210.543, 10, 139) -- Horlais Peek\n                            elseif option == 19 then\n                                player:setPos(-349.899, 104.213, -260.150, 0, 144) -- Waughrum Shrine\n                            elseif option == 20 then\n                                player:setPos(299.316, -123.591, 353.760, 66, 146) -- Balga's Dais\n                            elseif option == 21 then\n                                player:setPos(-225.146, -24.250, 20.057, 255, 206) -- Qu'bia Arena\n                            end\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/LB10_Beyond_Infinity.lua"]={["Path"]="scripts/quests/jeuno/LB10_Beyond_Infinity.lua",["SHA256"]="517a713ec2ff5faa2b6548c7b40678cbc3dbe21599e574d7e0351e2cb210d5cd",["Text"]="-----------------------------------\n-- Beyond Infinity\n-----------------------------------\n-- Log ID: 3, Quest ID: 137\n-- Nomad Moogle : !pos 10.012 1.453 121.883 243\n-----------------------------------\nlocal ruludeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.BEYOND_INFINITY)\n\nquest.reward =\n{\n    title = xi.title.BUSHIN_ASPIRANT,\n}\n\nlocal atoriBattlefieldIds =\n{\n    [xi.zone.BALGAS_DAIS]      = xi.battlefield.id.BEYOND_INFINITY_BALGAS_DAIS,\n    [xi.zone.HORLAIS_PEAK]     = xi.battlefield.id.BEYOND_INFINITY_HORLAIS_PEAK,\n    [xi.zone.QUBIA_ARENA]      = xi.battlefield.id.BEYOND_INFINITY,\n    [xi.zone.WAUGHROON_SHRINE] = xi.battlefield.id.BEYOND_INFINITY_WAUGHROON_SHRINE,\n}\n\nlocal atoriBattlefieldZone =\n{\n    onEventFinish =\n    {\n        [32001] = function(player, csid, option, npc)\n            local battlefieldWin = player:getLocalVar('battlefieldWin')\n\n            if battlefieldWin == atoriBattlefieldIds[player:getZoneID()] then\n                npcUtil.giveItem(player, xi.item.SCROLL_OF_INSTANT_WARP)\n                quest:setVar(player, 'Prog', 1)\n            end\n        end,\n    },\n}\n\nquest.sections =\n{\n    -- Section: Quest available.\n    -- Note: This step only happens with one, very specific option in the previous quest.\n    -- In most cases, the quest will already be accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.PRELUDE_TO_PUISSANCE) and\n                player:getLevelCap() == 95\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 0\n                    local lastQuestStage  = 0\n                    local rejectedOffer   = 0\n                    if\n                        xi.settings.main.MAX_LEVEL > 95 and\n                        limitBreaker == 1 and\n                        playerLevel > 90\n                    then\n                        lastQuestNumber = 5\n                        rejectedOffer   = player:getLocalVar('rejectedStartLB10')\n                    end\n\n                    return quest:progressEvent(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage, rejectedOffer)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10045] = function(player, csid, option, npc)\n                    -- This options start quest.\n                    if\n                        option == 13 or\n                        option == 14 or\n                        option == 19 or\n                        option == 20 or\n                        option == 21\n                    then\n                        quest:begin(player)\n                    end\n\n                    -- This options also warp you to a BCNM. Note that the quest \"Beyond Infinity\" is already activated.\n                    if option == 14 then\n                        player:setPos(-511.459, 159.004, -210.543, 10, xi.zone.HORLAIS_PEAK)\n                    elseif option == 19 then\n                        player:setPos(-349.899, 104.213, -260.150, 0, xi.zone.WAUGHROON_SHRINE)\n                    elseif option == 20 then\n                        player:setPos(299.316, -123.591, 353.760, 66, xi.zone.BALGAS_DAIS)\n                    elseif option == 21 then\n                        player:setPos(-225.146, -24.250, 20.057, 255, xi.zone.QUBIA_ARENA)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 0 and\n                player:hasKeyItem(xi.keyItem.SOUL_GEM_CLASP)\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 5\n                    local lastQuestStage  = 1\n\n                    return quest:event(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage)\n                end,\n            },\n\n            ['Maat'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(10193)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10045] = function(player, csid, option, npc)\n                    if option == 16 then\n                        player:setPos(-511.459, 159.004, -210.543, 10, xi.zone.HORLAIS_PEAK)\n                    elseif option == 22 then\n                        player:setPos(-349.899, 104.213, -260.150, 0, xi.zone.WAUGHROON_SHRINE)\n                    elseif option == 23 then\n                        player:setPos(299.316, -123.591, 353.760, 66, xi.zone.BALGAS_DAIS)\n                    elseif option == 24 then\n                        player:setPos(-225.146, -24.250, 20.057, 255, xi.zone.QUBIA_ARENA)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- BCNM Win Events.  Soul Gem Clasp is required for entry, and removed\n    -- after.  Separate section to not confuse with the failed event.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.BALGAS_DAIS]      = atoriBattlefieldZone,\n        [xi.zone.HORLAIS_PEAK]     = atoriBattlefieldZone,\n        [xi.zone.QUBIA_ARENA]      = atoriBattlefieldZone,\n        [xi.zone.WAUGHROON_SHRINE] = atoriBattlefieldZone,\n    },\n\n    -- Section: Quest accepted. We failed BCNM.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 0 and\n                not player:hasKeyItem(xi.keyItem.SOUL_GEM_CLASP)\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.HIGH_KINDREDS_CREST, 5 } }) then\n                        return quest:progressEvent(10195, 1)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local playerLevel     = player:getMainLvl()\n                    local limitBreaker    = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n                    local lastQuestNumber = 5\n                    local lastQuestStage  = 3 -- I guess failing is considered a new stage.\n                    local meritCost       = player:getMeritCount() >= 1 and 1 or 0\n\n                    return quest:progressEvent(10045, playerLevel, limitBreaker, lastQuestNumber, lastQuestStage, 0, 0, meritCost)\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [10045] = function(player, csid, option, npc)\n                    if option == 9 then\n                        local numMerits = player:getMeritCount()\n\n                        if numMerits >= 1 then\n                            player:setMerits(numMerits - 1)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10045] = function(player, csid, option, npc)\n                    if option ~= 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.SOUL_GEM_CLASP)\n                    end\n\n                    if option == 17 then\n                        player:setPos(-511.459, 159.004, -210.543, 10, xi.zone.HORLAIS_PEAK)\n                    elseif option == 25 then\n                        player:setPos(-349.899, 104.213, -260.150, 0, xi.zone.WAUGHROON_SHRINE)\n                    elseif option == 26 then\n                        player:setPos(299.316, -123.591, 353.760, 66, xi.zone.BALGAS_DAIS)\n                    elseif option == 27 then\n                        player:setPos(-225.146, -24.250, 20.057, 255, xi.zone.QUBIA_ARENA)\n                    end\n                end,\n\n                [10195] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.SOUL_GEM_CLASP)\n\n                    if option == 16 then\n                        player:setPos(-511.459, 159.004, -210.543, 10, xi.zone.HORLAIS_PEAK)\n                    elseif option == 22 then\n                        player:setPos(-349.899, 104.213, -260.150, 0, xi.zone.WAUGHROON_SHRINE)\n                    elseif option == 23 then\n                        player:setPos(299.316, -123.591, 353.760, 66, xi.zone.BALGAS_DAIS)\n                    elseif option == 24 then\n                        player:setPos(-225.146, -24.250, 20.057, 255, xi.zone.QUBIA_ARENA)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted. We beated the BCNM.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 1\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(10139, 75, 1)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10139] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setLevelCap(99)\n                        player:messageSpecial(ruludeID.text.YOUR_LEVEL_LIMIT_IS_NOW_99)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed.\n    -- TODO: Move all of this to \"martial mastery\" quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] =\n            {\n                onTrigger = function(player, npc)\n                    local playerLevel  = player:getMainLvl()\n                    local limitBreaker = player:hasKeyItem(xi.keyItem.LIMIT_BREAKER) and 1 or 2\n\n                    if\n                        player:getMainLvl() >= 99 and\n                        not player:hasKeyItem(xi.keyItem.JOB_BREAKER)\n                    then\n                        return quest:progressEvent(10240, playerLevel, limitBreaker)\n                    else\n                        return quest:event(10045, playerLevel, limitBreaker, 0, 0)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10240] = function(player, csid, option, npc)\n                    if option == 28 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.JOB_BREAKER)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Lakeside_Minuet.lua"]={["Path"]="scripts/quests/jeuno/Lakeside_Minuet.lua",["SHA256"]="2e9da5efd43748ba936c825f63c044138d01cde3cfe8f3395be5bd1916e33f31",["Text"]="-----------------------------------\n-- Lakeside Minuet\n-----------------------------------\n-- !addquest 3 95\n-- Laila           : !pos -54.045 -1 100.996 244\n-- Rhea Myuliah    : !pos -56.220 -1 101.805 244\n-- Valderotaux     : !pos 97 0.1 113 230\n-- Glowing Pebbles : !pos 104.2 4.1 443.6 82\n-----------------------------------\nlocal upperJeunoID = zones[xi.zone.UPPER_JEUNO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.LAKESIDE_MINUET)\n\nquest.reward =\n{\n    title = xi.title.TROUPE_BRILIOTH_DANCER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL and\n                xi.settings.main.ENABLE_WOTG == 1\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila'] = quest:progressEvent(10111),\n\n            onEventFinish =\n            {\n                [10111] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.STARDUST_PEBBLE) then\n                        return quest:progressEvent(10118)\n                    else\n                        return quest:progressEvent(10112)\n                    end\n                end,\n            },\n\n            ['Rhea_Myuliah'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(10113)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(10114)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(10115)\n                    elseif questProgress == 3 then\n                        if quest:getLocalVar(player, 'rheaOption') == 0 then\n                            return quest:progressEvent(10117)\n                        else\n                            return quest:progressEvent(10116)\n                        end\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(10121)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10113] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [10115] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [10116] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'rheaOption', 0)\n                end,\n\n                [10117] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'rheaOption', 1)\n                end,\n\n                [10118] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:unlockJob(xi.job.DNC)\n                        player:messageSpecial(upperJeunoID.text.UNLOCK_DANCER)\n                        player:delKeyItem(xi.keyItem.STARDUST_PEBBLE)\n                        npcUtil.giveKeyItem(player, xi.keyItem.JOB_GESTURE_DANCER)\n                        player:needToZone(true)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Valderotaux'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(888)\n                    elseif questProgress >= 2 then\n                        return quest:event(889)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [888] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.JUGNER_FOREST_S] =\n        {\n            ['Glowing_Pebbles'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 3 and\n                        not player:hasKeyItem(xi.keyItem.STARDUST_PEBBLE)\n                    then\n                        return quest:progressEvent(100)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [100] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.STARDUST_PEBBLE)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            }\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                not player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_UNFINISHED_WALTZ)\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Laila']        = quest:event(10119):replaceDefault(),\n            ['Rhea_Myuliah'] = quest:event(10126):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Lure_of_the_Wildcat_Jeuno.lua"]={["Path"]="scripts/quests/jeuno/Lure_of_the_Wildcat_Jeuno.lua",["SHA256"]="ad3eb7c815002366548800f9b6c6fca224d62ddce0c989d8b2b05f2c63c1034f",["Text"]="-----------------------------------\n-- Lure of the Wildcat (Jeuno)\n-----------------------------------\n-- !addquest 3 90\n-- Ajithaam : !pos -82 0.1 160 244\n-----------------------------------\nlocal upperJeunoID = zones[xi.zone.UPPER_JEUNO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.LURE_OF_THE_WILDCAT)\n\nquest.reward =\n{\n    keyItem  = xi.keyItem.WHITE_INVITATION_CARD,\n}\n\nlocal wildcatNpcData =\n{\n    ['Albiona'      ] = {  0, 10089 }, -- !pos -4.363 8.999 -31.901 243\n    ['Crooked_Arrow'] = {  1, 10090 }, -- !pos -34.9 2.999 -10.877 243\n    ['Muhoho'       ] = {  2, 10093 }, -- !pos -4.808 -4.999 27.83 243\n    ['Adolie'       ] = {  3, 10091 }, -- !pos -35 2 59 243\n    ['Yavoraile'    ] = {  4, 10092 }, -- !pos 30.173 2 68.864 243\n    ['Sibila-Mobla' ] = {  5, 10083 }, -- !pos -52.531 0 122.68 244\n    ['Shiroro'      ] = {  6, 10084 }, -- !pos -72.632 -1.2 52.905 244\n    ['Luto_Mewrilah'] = {  7, 10085 }, -- !pos -53 0 45 244\n    ['Renik'        ] = {  8, 10086 }, -- !pos -14.672 0 38.624 244\n    ['Hinda'        ] = {  9, 10087 }, -- !pos -25.605 -1.499 19.891 244\n    ['Sutarara'     ] = { 10, 10055 }, -- !pos 30 0.1 -2 245\n    ['Saprut'       ] = { 11, 10054 }, -- !pos 2.257 -5.999 -16.434 245\n    ['Bluffnix'     ] = { 12, 10056 }, -- !pos -43.099 5.9 -114.788 245\n    ['Naruru'       ] = { 13, 10053 }, -- !pos -56 0.1 -138 245\n    ['Gurdern'      ] = { 14, 10052 }, -- !pos -98.021 0 -142.601 245\n    ['Red_Ghost'    ] = { 15,   314 }, -- !pos -96.503 0 7.688 246\n    ['Karl'         ] = { 16,   316 }, -- !pos -60 0.1 -8 246\n    ['Shami'        ] = { 17,   317 }, -- !pos -53.9 0 10.8 246\n    ['Rinzei'       ] = { 18,   315 }, -- !pos -14.388 0 -9.156 246\n    ['Sagheera'     ] = { 19,   313 }, -- !pos -3 0.1 -9 246\n}\n\nlocal wildcatOnTrigger = function(player, npc)\n    local npcData = wildcatNpcData[npc:getName()]\n\n    if not quest:isVarBitsSet(player, 'Prog', npcData[1]) then\n        return quest:progressEvent(npcData[2])\n    end\nend\n\nlocal wildcatOnEventFinish = function(player, csid, option, npc)\n    quest:setVarBit(player, 'Prog', wildcatNpcData[npc:getName()][1])\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.settings.main.ENABLE_TOAU == 1\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Ajithaam'] = quest:progressEvent(10088),\n\n            onEventFinish =\n            {\n                [10088] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.WHITE_SENTINEL_BADGE)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Bluffnix'] = wildcatOnTrigger,\n            ['Gurdern' ] = wildcatOnTrigger,\n            ['Naruru'  ] = wildcatOnTrigger,\n            ['Saprut'  ] = wildcatOnTrigger,\n            ['Sutarara'] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [10052] = wildcatOnEventFinish,\n                [10053] = wildcatOnEventFinish,\n                [10054] = wildcatOnEventFinish,\n                [10055] = wildcatOnEventFinish,\n                [10056] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.PORT_JEUNO] =\n        {\n            ['Karl'     ] = wildcatOnTrigger,\n            ['Red_Ghost'] = wildcatOnTrigger,\n            ['Rinzei'   ] = wildcatOnTrigger,\n            ['Sagheera' ] = wildcatOnTrigger,\n            ['Shami'    ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [313] = wildcatOnEventFinish,\n                [314] = wildcatOnEventFinish,\n                [315] = wildcatOnEventFinish,\n                [316] = wildcatOnEventFinish,\n                [317] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Adolie'       ] = wildcatOnTrigger,\n            ['Albiona'      ] = wildcatOnTrigger,\n            ['Crooked_Arrow'] = wildcatOnTrigger,\n            ['Muhoho'       ] = wildcatOnTrigger,\n            ['Yavoraile'    ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [10089] = wildcatOnEventFinish,\n                [10090] = wildcatOnEventFinish,\n                [10091] = wildcatOnEventFinish,\n                [10092] = wildcatOnEventFinish,\n                [10093] = wildcatOnEventFinish,\n            },\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Ajithaam'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(10089)\n                    elseif utils.mask.isFull(questProgress, 20) then\n                        return quest:progressEvent(10091)\n                    else\n                        return quest:event(10090)\n                    end\n                end,\n            },\n\n            ['Hinda'        ] = wildcatOnTrigger,\n            ['Luto_Mewrilah'] = wildcatOnTrigger,\n            ['Renik'        ] = wildcatOnTrigger,\n            ['Shiroro'      ] = wildcatOnTrigger,\n            ['Sibila-Mobla' ] = wildcatOnTrigger,\n\n            onEventFinish =\n            {\n                [10083] = wildcatOnEventFinish,\n                [10084] = wildcatOnEventFinish,\n                [10085] = wildcatOnEventFinish,\n                [10086] = wildcatOnEventFinish,\n                [10087] = wildcatOnEventFinish,\n\n                [10091] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.WHITE_SENTINEL_BADGE)\n                    player:messageSpecial(upperJeunoID.text.KEYITEM_LOST, xi.keyItem.WHITE_SENTINEL_BADGE)\n\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Martial_Mastery.lua"]={["Path"]="scripts/quests/jeuno/Martial_Mastery.lua",["SHA256"]="fc99b98c7774e7ac958f81b21e718a2636476308cb11e5a574a3864526d23295",["Text"]="-----------------------------------\n-- Martial Mastery\n-----------------------------------\n-- !addquest 3 167\n-- Nomad Moogle : !pos 10.012 1.453 121.883 243\n-----------------------------------\nlocal ruLudeID = zones[xi.zone.RULUDE_GARDENS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.MARTIAL_MASTERY)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.HEART_OF_THE_BUSHIN,\n    title = xi.title.BUSHIN_RYU_INHERITOR,\n}\n\nlocal validCombatSkills =\n{\n    xi.skill.HAND_TO_HAND,\n    xi.skill.DAGGER,\n    xi.skill.SWORD,\n    xi.skill.GREAT_SWORD,\n    xi.skill.AXE,\n    xi.skill.GREAT_AXE,\n    xi.skill.SCYTHE,\n    xi.skill.POLEARM,\n    xi.skill.KATANA,\n    xi.skill.GREAT_KATANA,\n    xi.skill.CLUB,\n    xi.skill.STAFF,\n    xi.skill.ARCHERY,\n    xi.skill.MARKSMANSHIP,\n}\n\nlocal function hasRequiredCombatSkill(player)\n    for _, v in ipairs(validCombatSkills) do\n        if player:getSkillLevel(v) >= 357 then\n            return true\n        end\n    end\n\n    return false\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= 96 and\n                hasRequiredCombatSkill(player)\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] = quest:progressEvent(10196),\n\n            onEventFinish =\n            {\n                [10196] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            -- TODO: Confirm that the player must be on a valid job to complete\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:getMainLvl() >= 96 and\n                hasRequiredCombatSkill(player) and\n                player:getMeritCount() >= 15\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Nomad_Moogle'] = quest:progressEvent(10198),\n\n            onEventFinish =\n            {\n                [10198] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setMerits(player:getMeritCount() - 15)\n                        player:messageSpecial(ruLudeID.text.LEARNED_SECRET_TECHNIQUE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Mysteries_of_Beadeaux_I.lua"]={["Path"]="scripts/quests/jeuno/Mysteries_of_Beadeaux_I.lua",["SHA256"]="f3f5e7d65d6bc00344e835082ca1c1e51419d13324949a47ab69249197d55cac",["Text"]="-----------------------------------\n-- Mysteries of Beadeaux I\n-----------------------------------\n-- Log ID: 3, Quest ID: 31\n-- Sattal-Mansal : !pos 40 3 -53 245\n-----------------------------------\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.MYSTERIES_OF_BEADEAUX_I)\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasKeyItem(xi.keyItem.SILVER_BELL)\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Sattal-Mansal'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(89, 0)\n                end,\n            },\n\n            onEventFinish =\n            {\n                -- This event flags both Mysteries of Beadeaux I and II\n                [89] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.MYSTERIES_OF_BEADEAUX_II)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Sattal-Mansal'] =\n            {\n                -- Retail hands over the reward as the event starts. The message prints when it ends.\n                onTrade = function(player, npc, trade)\n                    if not npcUtil.tradeMatches(trade, { { xi.item.QUADAV_CHARM, 1 } }) then\n                        return\n                    end\n\n                    player:addKeyItem(xi.keyItem.CORUSCANT_ROSARY)\n                    player:addFame(xi.fameArea.SANDORIA, 7)\n                    player:addFame(xi.fameArea.BASTOK, 7)\n                    player:addFame(xi.fameArea.WINDURST, 7)\n                    player:tradeComplete()\n\n                    return quest:progressEvent(91)\n                end,\n\n                -- Param 0 flags the offer as already taken.\n                onTrigger = quest:event(89, 1),\n            },\n\n            onEventFinish =\n            {\n                [91] = function(player, csid, option, npc)\n                    player:completeQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.MYSTERIES_OF_BEADEAUX_I)\n                    player:messageSpecial(lowerJeunoID.text.KEYITEM_OBTAINED, xi.keyItem.CORUSCANT_ROSARY)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Mysteries_of_Beadeaux_II.lua"]={["Path"]="scripts/quests/jeuno/Mysteries_of_Beadeaux_II.lua",["SHA256"]="cdf5716018d81d824ceee9f8cae8f1ae99fd5907894f977305316e124bb3736c",["Text"]="-----------------------------------\n-- Mysteries of Beadeaux II\n-----------------------------------\n-- Log ID: 3, Quest ID: 32\n-- Sattal-Mansal : !pos 40 3 -53 245\n-----------------------------------\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.MYSTERIES_OF_BEADEAUX_II)\n\nquest.sections =\n{\n    -- This quest is flagged from an event contained in Mysteries of Beadeaux I\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Sattal-Mansal'] =\n            {\n                -- Retail hands over the reward as the event starts. The message prints when it ends.\n                onTrade = function(player, npc, trade)\n                    if not npcUtil.tradeMatches(trade, { { xi.item.QUADAV_AUGURY_SHELL, 1 } }) then\n                        return\n                    end\n\n                    player:addKeyItem(xi.keyItem.BLACK_MATINEE_NECKLACE)\n                    player:addFame(xi.fameArea.SANDORIA, 7)\n                    player:addFame(xi.fameArea.BASTOK, 7)\n                    player:addFame(xi.fameArea.WINDURST, 7)\n                    player:tradeComplete()\n\n                    return quest:progressEvent(92)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [92] = function(player, csid, option, npc)\n                    player:completeQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.MYSTERIES_OF_BEADEAUX_II)\n                    player:messageSpecial(lowerJeunoID.text.KEYITEM_OBTAINED, xi.keyItem.BLACK_MATINEE_NECKLACE)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Never_to_Return.lua"]={["Path"]="scripts/quests/jeuno/Never_to_Return.lua",["SHA256"]="94fbd5f51b80c5f0e6870f593e83665399e6a747834e764f242d04d0ba1a453b",["Text"]="-----------------------------------\n-- Never to Return\n-----------------------------------\n-- Log ID: 3, Quest ID: 14\n-- Kurou-Morou : !pos -4 -6 -28 245\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.NEVER_TO_RETURN)\n\nquest.reward =\n{\n    gil  = 1200,\n    item = xi.item.GARNET_RING,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.YOUR_CRYSTAL_BALL)\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Kurou-Morou'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') >= 3 and\n                        quest:getVar(player, 'Day') ~= VanadielUniqueDay() and\n                        player:getFameLevel(xi.fameArea.JEUNO) >= 5\n                    then\n                        return quest:progressEvent(202) -- Quest offered\n                    end\n\n                    return quest:event(204) -- Fortune reading\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [204] = function(player, csid, option, npc)\n                    player:updateEvent((VanadielUniqueDay() + player:getID()) % 100)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [202] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n\n                [204] = function(player, csid, option, npc)\n                    if\n                        option == 0 and\n                        quest:getVar(player, 'Day') ~= VanadielUniqueDay()\n                    then\n                        quest:setVar(player, 'Prog', quest:getVar(player, 'Prog') + 1)\n                        quest:setVar(player, 'Day', VanadielUniqueDay())\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Kurou-Morou'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(203) -- Reminder\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.HORN_HAIRPIN, 1 } }) then\n                        return quest:progressEvent(201) -- Quest complete\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [201] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                        player:addFame(xi.fameArea.SANDORIA, 17)\n                        player:addFame(xi.fameArea.BASTOK, 17)\n                        player:addFame(xi.fameArea.WINDURST, 17)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Kurou-Morou'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(204) -- Fortune reading\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [204] = function(player, csid, option, npc)\n                    player:updateEvent((VanadielUniqueDay() + player:getID()) % 100)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Northward.lua"]={["Path"]="scripts/quests/jeuno/Northward.lua",["SHA256"]="8b798c442d580a7d436da22bcc84459fbfea441382a88dbe00d36da15ac4796b",["Text"]="-----------------------------------\n-- Northward\n-----------------------------------\n-- Log ID: 3, Quest ID: 24\n-- Radeivepart : !pos 5 9 -39 243\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.NORTHWARD)\n\nquest.reward =\n{\n    exp      = 2000,\n    gil      = 2000,\n    keyItem  = xi.keyItem.MAP_OF_CASTLE_ZVAHL,\n    title    = xi.title.ENVOY_TO_THE_NORTH,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.JEUNO) >= 4\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Radeivepart'] = quest:progressEvent(159, { [0] = 1, [7] = 8 }),\n\n            onEventFinish =\n            {\n                [159] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Radeivepart'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.FLAME_DEGEN) then\n                        return quest:progressEvent(61)\n                    end\n                end,\n\n                onTrigger = quest:event(159, { [0] = 2, [7] = 8 }),\n            },\n\n            onEventFinish =\n            {\n                [61] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 13)\n                        player:addFame(xi.fameArea.BASTOK, 13)\n                        player:addFame(xi.fameArea.WINDURST, 13)\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.RULUDE_GARDENS] =\n        {\n            ['Radeivepart'] = quest:event(159, { [0] = 3, [7] = 8 }):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Painful_Memory.lua"]={["Path"]="scripts/quests/jeuno/Painful_Memory.lua",["SHA256"]="56595c5aee038205026cdadb19e326103bd64423f9f0cea231862fd8c1707edc",["Text"]="-----------------------------------\n-- Painful Memory\n-----------------------------------\n-- Log ID: 3, Quest ID: 63\n-- Mertaire           !pos -17 0 -61 245\n-- Waters of Oblivion !pos -289 -45 212 166\n-----------------------------------\nlocal ID = zones[xi.zone.RANGUEMONT_PASS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.PAINFUL_MEMORY)\n\nquest.reward =\n{\n    item  = xi.item.PAPER_KNIFE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.PATH_OF_THE_BARD) and\n                player:getMainJob() == xi.job.BRD and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n\n            ['Mertaire'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 0 then\n                        return quest:progressEvent(138)\n                    else\n                        return quest:progressEvent(137) -- Player declined\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [137] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.MERTAIRES_BRACELET)\n                    end\n                end,\n\n                [138] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Option', 1) -- Player declined\n                    else\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.MERTAIRES_BRACELET)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Mertaire'] = quest:event(136),\n        },\n\n        [xi.zone.RANGUEMONT_PASS] =\n        {\n            ['Tros'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n\n            ['Waters_of_Oblivion'] =\n            {\n                onTrigger = function(player, npc)\n                    local progress = quest:getVar(player, 'Prog')\n\n                    if\n                        player:hasKeyItem(xi.keyItem.MERTAIRES_BRACELET) and\n                        progress == 0\n                    then\n                        npcUtil.popFromQM(player, npc, ID.mob.TROS, { claim = true, hide = 0 }) -- TODO: Should not spawn claimed but navmesh+line of sight make it to where the player can't engage with the mob on spawn.\n                        return quest:noAction() -- No message\n                    elseif progress == 1 then\n                        return quest:progressCutscene(8) -- TODO: Confirm agro is dropped when CS is triggered\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addFame(xi.fameArea.SANDORIA, 7)\n                        player:addFame(xi.fameArea.BASTOK, 7)\n                        player:addFame(xi.fameArea.WINDURST, 7)\n                        player:delKeyItem(xi.keyItem.MERTAIRES_BRACELET)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Mertaire'] = quest:event(135)\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Path_of_the_Bard.lua"]={["Path"]="scripts/quests/jeuno/Path_of_the_Bard.lua",["SHA256"]="7218f9f6fb8a255cc68ab2f06d39e7adf4529d27e5b883fdec56d968af75d916",["Text"]="-----------------------------------\n-- Path of the Bard\n-----------------------------------\n-- Log ID: 3, Quest ID: 20\n-- Song Runes !pos -721 -7 102 103\n-----------------------------------\nlocal valkrumID    = zones[xi.zone.VALKURM_DUNES]\nlocal lowerJeunoID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.PATH_OF_THE_BARD)\n\nquest.reward =\n{\n    gil      = 3000,\n    keyItem  = xi.keyItem.JOB_GESTURE_BARD,\n    title    = xi.title.WANDERING_MINSTREL,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n            player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.A_MINSTREL_IN_DESPAIR) == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        -- It was found that all of the dialogue is optional and the player can go straight to the song runes in Valkrum Dunes upon finishing A Minstrel in Despair\n        [xi.zone.LOWER_JEUNO] =\n        {\n\n            ['Bki_Tbujhja'] = quest:event(182),\n\n            ['Mataligeat'] = quest:event(144),\n\n            ['Mertaire'] = quest:messageName(lowerJeunoID.text.COULD_HE_BE, 0, 0, 0, 0, true, false),\n\n        },\n\n        [xi.zone.VALKURM_DUNES] =\n        {\n            ['Song_Runes'] = quest:progressCutscene(2),\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:unlockJob(xi.job.BRD)\n                    player:messageSpecial(valkrumID.text.UNLOCK_BARD)\n                    quest:complete(player)\n                    player:addFame(xi.fameArea.SANDORIA, 7)\n                    player:addFame(xi.fameArea.BASTOK, 7)\n                    player:addFame(xi.fameArea.WINDURST, 7)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.LOWER_JEUNO] =\n        {\n            ['Bki_Tbujhja'] = quest:event(180),\n\n            ['Mataligeat'] = quest:event(143),\n\n            ['Mertaire'] =\n            {\n            onTrigger = function(player, npc)\n                    if player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.PAINFUL_MEMORY) == xi.questStatus.QUEST_AVAILABLE then\n                        return quest:event(103) -- Plays after this quest is complete and before the player meets the requirements to start \"Painful Memory\"\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/jeuno/Path_of_the_Beastmaster.lua"]={["Path"]="scripts/quests/jeuno/Path_of_the_Beastmaster.lua",["SHA256"]="c256006dba14d96b31322da84d29e3c00622a89e3f9507e60306d054acc63836",["Text"]="-----------------------------------\n-- Path of the Beastmaster\n-----------------------------------\n-- Log ID: 3, Quest ID: 19\n-- Brutus : !pos -55 8 95 244\n-----------------------------------\nlocal upperJeunoID = zones[xi.zone.UPPER_JEUNO]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.JEUNO, xi.quest.id.jeuno.PATH_OF_THE_BEASTMASTER)\n\nquest.reward =\n{\n    keyItem  = xi.keyItem.JOB_GESTURE_BEASTMASTER,\n    title    = xi.title.ANIMAL_TRAINER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.SAVE_MY_SON) and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus'] = quest:progressEvent(70),\n\n            onEventFinish =\n            {\n                [70] = function(player, csid, option, npc)\n                    player:unlockJob(xi.job.BST)\n                    player:messageSpecial(upperJeunoID.text.YOU_CAN_NOW_BECOME_A_BEASTMASTER)\n                    quest:complete(player)\n                    player:addFame(xi.fameArea.SANDORIA, 7)\n                    player:addFame(xi.fameArea.BASTOK, 7)\n                    player:addFame(xi.fameArea.WINDURST, 7)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Brutus']  = quest:event(20),\n            ['Chocobo'] = quest:event(72):replaceDefault(),\n            ['Osker']   = quest:event(45):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"}};
